import wave, numpy as np
with wave.open('/root/video_work/audio.wav','rb') as w:
    sr=w.getframerate(); x=np.frombuffer(w.readframes(w.getnframes()),dtype=np.int16).astype(np.float32)/32768
frame=int(sr*.02); hop=frame//2
frames=np.lib.stride_tricks.sliding_window_view(x,frame)[::hop]
rms=np.sqrt(np.mean(frames**2,axis=1)+1e-12); db=20*np.log10(np.maximum(rms,1e-9)); step=hop/sr
print(f'audio sr={sr} frames={len(rms)} step={step:.3f}s duration={len(x)/sr:.3f}s')
for q in [1,2,5,10,25,50,75,90,95,99]: print(f'p{q}={np.percentile(db,q):.1f}',end=' ')
print('\n\nOne-second summary where quiet:')
for sec in range(int(np.ceil(len(x)/sr))):
    a=int(sec/step); b=min(len(db),int((sec+1)/step))
    if b<=a: continue
    q10,q50,q90=np.percentile(db[a:b],[10,50,90])
    if q50 < -42 or (q10 < -50 and q90 < -35): print(f'{sec:3d}-{sec+1:3d}: p10={q10:5.1f} p50={q50:5.1f} p90={q90:5.1f}')
# use thresholds and contiguous runs, report durations and internal max/percentiles
def runs(mask):
    out=[]; s=None
    for i,v in enumerate(np.r_[mask,False]):
        if v and s is None: s=i
        elif not v and s is not None:
            out.append((s,i)); s=None
    return out
for threshold in [-38,-40,-42,-44,-46]:
    print(f'\nRuns with every 20ms frame <= {threshold} dBFS (>=1.5s):')
