print('\nRuns after smoothing 0.5s mean <= -38 dBFS (>=1.5s):')
sm=np.convolve(db,np.ones(int(.5/step))/int(.5/step),mode='same')
for s,e in runs(sm<=-38):
    # trim edge artifacts
    if (e-s)*step >= 1.5: print(f'{s*step:.3f}-{e*step:.3f} dur={(e-s)*step:.3f}, smmax={sm[s:e].max():.1f}')
