frame=int(sr*.02); hop=frame//2
frames=np.lib.stride_tricks.sliding_window_view(x,frame)[::hop]
rms=np.sqrt(np.mean(frames**2,axis=1)+1e-12); db=20*np.log10(np.maximum(rms,1e-9)); step=hop/sr
print(f'audio sr={sr} frames={len(rms)} step={step:.3f}s duration={len(x)/sr:.3f}s')
for q in [1,2,5,10,25,50,75,90,95,99]: print(f'p{q}={np.percentile(db,q):.1f}',end=' ')
print('\n\nOne-second summary where quiet:')
for sec in range(int(np.ceil(len(x)/sr))):
